function getRealMovieMedia(movieId) {
  const media = realMovieMedia[movieId] ?? null;
  if (!media) return null;
  return {
    ...media,
    poster: isReusableMovieImage(media.poster) ? media.poster : "",
    backdrop: isReusableMovieImage(media.backdrop) ? media.backdrop : "",
  };
}

function getRealCastAvatar(movieId, name) {
  return realMovieMedia[movieId]?.cast?.[name] ?? "";
}

function isReusableMovieImage(value) {
  const image = String(value || "");
  return (
    isCloudinaryImage(image) &&
    !isCastMediaImage(image) &&
    !image.includes("l_text:") &&
    !image.startsWith("data:")
  );
}

function isCloudinaryImage(value) {
  return /^https:\/\/res\.cloudinary\.com\//.test(String(value || ""));
}

function isCastMediaImage(value) {
  return /\/(?:real-cast|cast)\//.test(String(value || ""));
}

export { getRealCastAvatar, getRealMovieMedia, realMovieMedia };
